-- gaps: 1 insert(s), 0 update(s)
INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-010', 'EG', 'P1', 'OPEN', NULL, NULL, 'IS REF-01001 Co-1? THE ANSWER DECIDES WHETHER PARAMETER 3 IS STILL A PROXY, AND IT CANNOT BE SETTLED FROM THE ABSTRACT. Lepoglavec et al. 2023 (10.3390/su15107741) derives two gradient thresholds FROM MEASUREMENT of eight wheelchair-using subjects -- 5.50% as the tipping point after which all respondents experienced uncertainty, and >9.01% as almost impassable on the gravel trails examined. Its Crossref-deposited abstract states: ''people with disabilities were included in the implementation of the research through the Croatian Association of Paraplegics and Tetraplegics (HUPT)''. THAT NAMES AN ORGANISATION, which is exactly what add-source --co1-provenance demands. WHY IT IS NOT FILED AS Co-1 TODAY: ''included in the implementation'' does not distinguish CO-PRODUCTION from PARTICIPATION AS SUBJECTS, and D-0178 draws precisely that line. CLAUDE.md section 6 holds that Co-1''s warrant IS co-production and that erasing the disabled people who produced a work while claiming the tier is the worst failure available here; the symmetric error -- claiming the tier on an ambiguous sentence -- is the one being refused now. Admitted instead at the tier the ratified ladder derives from what is verifiable: clinical + lower_control = T3, a field study on real trails with no control condition. WHY IT MATTERS: specification 7 rests_on_proxy_inference=1 solely because every governing claim it holds is T4-T6 regulatory and no anchoring-tier source states a value. Co-1 is CO-PRIMARY with T1 under CRPD Art 4.3. So if the HUPT involvement is co-production, this source is anchoring-tier, it states values, and it satisfies specification 7''s own falsification condition -- and parameter 3 stops being a proxy determination. If it is participation only, the row stays T3 and the proxy stands. RESOLUTION PATH: MDPI is Akamai-blocked (HTTP Access Denied, artefact persisted this session); read the full text via a repository or library route and look for the methods statement describing HUPT''s role. Do not promote the two extractions (42, 43) or cite the figures until that read happens -- both are extraction_status=preliminary, extraction_method=skim for this reason.', '2026-09-18 04:20', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:20', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', NULL, NULL, NULL, NULL, NULL);

-- search_executions: 1 insert(s), 0 update(s)
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (65, 'accessible-circulation-geometry', NULL, 'EN', 1, 'co1', NULL, 'disabled people''s organisation wheelchair user first-person account ramp gradient too steep independent access', NULL, 'consensus', 'systematic', 'none', 10, 10, 1, 'partial', NULL, NULL, 0, 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:21', 'PRIOR FALSIFIED ON THE ONE CLAUSE THAT MATTERED. I predicted testimonial-not-dimensional; the top hit is DIMENSIONAL AND CO-PRODUCED. REF-01001 (Lepoglavec 2023, Sustainability) derives 5.50% as the tipping point after which all eight wheelchair-using subjects experienced uncertainty, and >9.01% as almost impassable on gravel, from instrumented field measurement -- GNSS and geodetic station, heart-rate telemetry -- and states that people with disabilities were included in the implementation of the research through the Croatian Association of Paraplegics and Tetraplegics (HUPT), a NAMED organisation. THE Co-1 QUESTION IS THEREFORE LIVE AND DECISIVE, and it is raised as GAP-010 rather than answered here: ''included in the implementation'' does not separate co-production from participation-as-subjects (D-0178), MDPI is Akamai-blocked, and admitting Co-1 on an ambiguous sentence is the mirror of the failure CLAUDE.md section 6 forbids. Admitted at the ladder-derived T3 (clinical + lower_control) in the meantime. ALSO SURFACED, staged not admitted: Pettersson 2022, a thematic analysis of 88 discrimination complaints filed with the Swedish Equality Ombudsman by wheeled-mobility-device users -- first-person accounts routed through a national equality body, which is a Co-1-adjacent shape this corpus has no instance of. Overlap with REF-00977/00999/01000 confirms partial saturation on the qualitative seam opened at exec 64.', 0, 'The Co-1 seam for ramps has been worked hard -- batch 09 admitted REF-00989 and REF-00993, batches 13-14 found the professional-body route empty -- so expect LOW yield and high overlap, and expect any new material to be testimonial rather than dimensional. Expect 0-1 admissions. FALSIFIED IF a disabled people''s organisation states or contests a gradient figure, which would be a Co-1 value meeting spec 7''s falsification condition from the co-primary side.');

