-- search_candidates: 1 insert(s), 0 update(s)
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at") VALUES (95, 65, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Pettersson C et al. (2022). The struggle for access - a qualitative document study of how people using wheeled mobility devices experience exclusion and discrimination. Disability and Rehabilitation: Assistive Technology', 'DOI not confirmed this batch -- do NOT reuse a guessed DOI', NULL, 3, 1, 'Not retrieved this batch; surfaced late in the Co-1 pass after the batch''s admissions were already filed and the migration path begun.', 'Co-1-ADJACENT SHAPE THIS CORPUS HAS NO INSTANCE OF: a thematic analysis of 88 discrimination complaints filed with the Swedish Equality Ombudsman by people using wheeled mobility devices. The evidence is first-person accounts routed through a national equality body -- neither a researcher-designed survey nor a DPO publication, but testimony given for a legal purpose. Its three themes are argument-level and directly relevant: invoking law and highlighting non-compliance; demanding to be recognised and listened to; and struggling for equal access. Its own implications section says the difficulties reported can reveal knowledge important for REVISING existing design and renovation standards -- a code-insufficiency argument grounded in complaint data. R15 hypothesis; confirm the DOI and whether ramps or gradients appear specifically.', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:22');

