INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (42, 'REF-01001', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'HR', NULL, 'numerical', '5.50', '%', 'The results indicate that a slope of 5.50% was the tipping point, after which all respondents experienced some uncertainty.', 'Abstract (Crossref-deposited)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'DERIVED FROM MEASUREMENT, NOT RESTATED FROM A CODE -- the distinction that matters for parameter 3, whose determination is a PROXY precisely because every governing claim it holds is regulatory. Eight wheelchair-using subjects over six gravel trails, instrumented with GNSS/geodetic survey and heart-rate telemetry. Filed as finding rather than claim: a tipping point above which uncertainty begins is not a stated design ceiling. extraction_method=skim and status=preliminary because MDPI is Akamai-blocked and this rests on the Crossref-deposited abstract; the full text must be read before this is promoted or cited.', '2026-09-18 04:20', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:20', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', 'finding', '>');
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (43, 'REF-01001', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'HR', NULL, 'numerical', '9.01', '%', 'In addition, a gradient of more than 9.01% was almost impassable for people in wheelchairs, with respect to the gravel trails examined in this study.', 'Abstract (Crossref-deposited)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'skim', 'preliminary', NULL, 'The impassability bound from the same study. CONDITIONED ON SURFACE, which no other row in this corpus is: the source scopes it explicitly to the gravel trails examined, so it must NOT be read as a bound for a bound/paved ramp. Note the direction of the evidence against the codes: 9.01% is GENTLER than the 1:8 (12.5%) that Japanese law and SA prescriber guidance both permit as a small-rise exception, and 5.50% sits just above the 5% ceiling that specification 7 currently determines.', '2026-09-18 04:20', 'session_2026-09-18-research-batch-15-t2-synthesis-threshold', '2026-09-18 04:20', 'session_2026-09-18-research-batch-